const rootFolderId = $json.ROOT_FOLDER_ID;
if (!rootFolderId || rootFolderId === 'REEMPLAZAR_CON_ID_CARPETA_DRIVE') {
  throw new Error('ROOT_FOLDER_ID no configurado');
}
return [{
  json: {
    ...$json,
    rootFolderId,
    folderQueue: [rootFolderId],
    folderMeta: {
      [rootFolderId]: { id: rootFolderId, name: null, root_category: null, path: [] },
    },
    files: [],
    skippedFolders: [],
    stage1_sync_only: true,
  },
}];

const state = { ...$json };
state.folderQueue = Array.isArray(state.folderQueue) ? [...state.folderQueue] : [];
state.folderMeta = state.folderMeta || {};
state.files = Array.isArray(state.files) ? [...state.files] : [];
state.skippedFolders = Array.isArray(state.skippedFolders) ? [...state.skippedFolders] : [];

const currentFolderId = state.folderQueue.shift();
if (!currentFolderId) return [];
const currentFolderMeta = state.folderMeta[currentFolderId] || {
  id: currentFolderId,
  name: null,
  root_category: null,
  path: [],
};

return [{ json: { ...state, currentFolderId, currentFolderMeta } }];

const state = { ...$('Preparar carpeta actual').item.json };
const currentFolderId = state.currentFolderId;
const currentMeta = state.currentFolderMeta || state.folderMeta?.[currentFolderId] || { path: [], category_path: [] };
const children = $json.files || [];
const PROCESS_YEAR = '2026';

function normalizeName(value) {
  return String(value || '').trim();
}

function explicitYears(value) {
  const text = String(value || '');
  const years = new Set();
  for (const match of text.matchAll(/(?:^|[^0-9])((?:19|20)\d{2})(?:[^0-9]|$)/g)) years.add(match[1]);
  for (const match of text.matchAll(/(?:^|[^0-9])(0?[1-9]|1[0-2])[-_. ]([0-9]{2})(?:[^0-9]|$)/g)) {
    years.add(String(2000 + Number(match[2])));
  }
  return [...years];
}

function isYearSegment(value) {
  return /^(?:19|20)\d{2}$/.test(normalizeName(value));
}

function hasNonProcessYear(value) {
  return explicitYears(value).some((year) => year !== PROCESS_YEAR);
}

state.folderQueue = Array.isArray(state.folderQueue) ? [...state.folderQueue] : [];
state.folderMeta = state.folderMeta || {};
state.files = Array.isArray(state.files) ? [...state.files] : [];
state.skippedFolders = Array.isArray(state.skippedFolders) ? [...state.skippedFolders] : [];
state.skippedFiles = Array.isArray(state.skippedFiles) ? [...state.skippedFiles] : [];

for (const child of children) {
  const name = normalizeName(child.name);
  const path = [...(currentMeta.path || []), child.name];

  if (child.mimeType === 'application/vnd.google-apps.folder') {
    if (isYearSegment(name) && name !== PROCESS_YEAR) {
      state.skippedFolders.push({ id: child.id, name: child.name, path: path.join('/'), reason: 'folder_year_not_2026' });
      continue;
    }

    if (!isYearSegment(name) && hasNonProcessYear(name)) {
      state.skippedFolders.push({ id: child.id, name: child.name, path: path.join('/'), reason: 'folder_name_indicates_non_2026_year' });
      continue;
    }

    const categoryPath = isYearSegment(name)
      ? [...(currentMeta.category_path || [])]
      : [...(currentMeta.category_path || []), child.name];

    state.folderMeta[child.id] = {
      id: child.id,
      name: child.name,
      parent_id: currentFolderId,
      path,
      category_path: categoryPath,
    };
    state.folderQueue.push(child.id);
    continue;
  }

  if (hasNonProcessYear(name)) {
    state.skippedFiles.push({
      id: child.id,
      name: child.name,
      path: path.join('/'),
      reason: 'file_name_indicates_non_2026_year',
    });
    continue;
  }

  const categoryPath = [...(currentMeta.category_path || [])];
  state.files.push({
    ...child,
    drive_file_id: child.id,
    discovered_parent_id: currentFolderId,
    drive_path: path.join('/'),
    category_path: categoryPath,
    processing_year: Number(PROCESS_YEAR),
  });
}

delete state.currentFolderId;
delete state.currentFolderMeta;
return [{ json: state }];

const files = Array.isArray($json.files) ? $json.files : [];
return files.map((file) => ({
  json: {
    ...file,
    ROOT_FOLDER_ID: $json.ROOT_FOLDER_ID,
    rootFolderId: $json.rootFolderId,
    skippedFolders: $json.skippedFolders || [],
    stage1_sync_only: true,
  },
}));

const files = $('Emitir archivos').all().map((item) => item.json);
return items.map((item, index) => {
  const file = files[index] || item.json;
  const lookup = item.json || {};
  const existingDocument = lookup.existing_document || null;
  const documentExists = lookup.document_exists === true || lookup.document_exists === 'true';
  const existingStatus = lookup.existing_processing_status || existingDocument?.processing_status || null;
  const existingModifiedAt = lookup.existing_file_modified_at || existingDocument?.extracted_data?.file_modified_at || null;
  const currentModifiedAt = file.modifiedTime || null;
  const modifiedChanged = !!currentModifiedAt && !!existingModifiedAt
    ? new Date(currentModifiedAt).getTime() !== new Date(existingModifiedAt).getTime()
    : !documentExists;
  const extractedData = existingDocument?.extracted_data || {};
  const waitingForOcr = extractedData.source_kind === 'pdf_scanned'
    || extractedData.source_kind === 'image'
    || (Array.isArray(extractedData.review_reasons) && (
      extractedData.review_reasons.includes('pdf_without_extractable_text_or_scanned')
      || extractedData.review_reasons.includes('image_requires_ocr_or_vision')
    ));
  const missingCriticalField = !existingDocument?.raw_text
    || !existingDocument?.amount
    || !existingDocument?.payment_date
    || !existingDocument?.reason
    || !existingDocument?.reference
    || !existingDocument?.issuer;
  const needsExtraction = documentExists
    && !waitingForOcr
    && (['review_required', 'error'].includes(existingStatus) || missingCriticalField);
  const shouldDownload = !documentExists || modifiedChanged || needsExtraction;

  return {
    json: {
      ...file,
      lookup,
      document_exists: documentExists,
      existing_processing_status: existingStatus,
      waitingForOcr,
      needsExtraction,
      should_download: shouldDownload,
      processing_decision: shouldDownload ? (needsExtraction ? 'retry_extraction' : (documentExists ? 'modified' : 'new')) : 'unchanged_seen',
    },
  };
});

return items.map((item, index) => {
  const source = $('Decidir procesamiento').all()[index]?.json || $('Decidir procesamiento').item.json;
  const sha256 = item.json.sha256 || item.json.data || null;
  const driveMd5Checksum = source.md5Checksum || source.drive_md5_checksum || null;
  return {
    json: {
      ...source,
      sha256,
      content_hash: sha256,
      content_hash_algorithm: sha256 ? 'sha256' : null,
      drive_md5_checksum: driveMd5Checksum,
    },
    binary: item.binary,
  };
});

return items.map((item) => {
  const mimeType = item.json.mimeType || '';
  const source_kind = mimeType.startsWith('image/') ? 'image' : null;
  return {
    json: {
      ...item.json,
      source_kind,
      raw_text: null,
      extracted_data: {
        stage: 'stage1_metadata_only',
        drive_path: item.json.drive_path || null,
        md5Checksum: item.json.md5Checksum || null,
        size: item.json.size || null,
      },
      field_sources: {
        root_category: 'drive_first_folder_under_root',
        file_name: 'google_drive',
        drive_file_id: 'google_drive',
        sha256: 'downloaded_binary',
      },
      field_confidence: {},
      needs_review: false,
      review_reasons: [],
      processing_status: 'pending',
    },
    binary: item.binary,
  };
});

function normalizeWhitespace(value) {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

function parseDate(text) {
  const match = text.match(/\b(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{2,4})\b/);
  if (!match) return null;
  const day = Number(match[1]);
  const month = Number(match[2]);
  let year = Number(match[3]);
  if (year < 100) year += 2000;
  if (month < 1 || month > 12 || day < 1 || day > 31) return null;
  return String(year).padStart(4, '0') + '-' + String(month).padStart(2, '0') + '-' + String(day).padStart(2, '0');
}

function parseAmount(text) {
  function toNumber(raw) {
    if (!raw) return null;
    const normalized = raw.includes(',')
      ? raw.replace(/\./g, '').replace(',', '.')
      : raw.replace(/,/g, '');
    const amount = Number(normalized);
    return Number.isFinite(amount) ? amount : null;
  }

  function formatAmount(amount) {
    return Number.isFinite(amount) ? amount.toFixed(2) : null;
  }

  function debitTokenToAmount(raw) {
    let token = String(raw || '').trim();
    const gluedCodeMatch = token.match(/^\d{5}(\d{1,3}(?:\.\d{3})*,\d{2})$/);
    if (gluedCodeMatch) token = gluedCodeMatch[1];
    return toNumber(token);
  }

  const debitMovementAmounts = [];
  if (/Detalle\s+de\s+movimientos/i.test(text) && /D[eé]bito\s+Cr[eé]dito/i.test(text)) {
    const debitPattern = /\b(\d{5,6}\d{1,3}(?:\.\d{3})*,\d{2}|[0-9]{1,3}(?:\.[0-9]{3})*,[0-9]{2})\s+0,00/gi;
    for (const match of text.matchAll(debitPattern)) {
      const amount = debitTokenToAmount(match[1]);
      if (amount && amount > 0) debitMovementAmounts.push(amount);
    }
    if (debitMovementAmounts.length) {
      return formatAmount(debitMovementAmounts.reduce((sum, amount) => sum + amount, 0));
    }
  }

  const candidates = [];
  const amountToken = '([0-9]{1,3}(?:[.,][0-9]{3})*(?:[.,][0-9]{2})|[0-9]+(?:[.,][0-9]{2}))';
  const patterns = [
    new RegExp('Vencimiento\\s+Importe[\\s\\S]{0,120}?\\b\\d{1,2}[\\/.-]\\d{1,2}[\\/.-]\\d{2,4}\\s+' + amountToken, 'gi'),
    new RegExp('Vencimiento\\s+Importe\\s+Cuota\\s+Cod\\.Seg\\.[\\s\\S]{0,80}?\\s+' + amountToken + '\\s+\\d{6,}', 'gi'),
    /(?:total|importe|monto|abonado|pagado|pago)\s*[:$]?\s*(?:ars|\$)?\s*([0-9]{1,3}(?:[.,][0-9]{3})*(?:[.,][0-9]{2})|[0-9]+(?:[.,][0-9]{2}))/gi,
    /(?:ars|\$)\s*([0-9]{1,3}(?:[.,][0-9]{3})*(?:[.,][0-9]{2})|[0-9]+(?:[.,][0-9]{2}))/gi
  ];
  for (const pattern of patterns) {
    for (const match of text.matchAll(pattern)) candidates.push(match[1]);
  }
  if (!candidates.length) return null;
  const raw = candidates[candidates.length - 1];
  return formatAmount(toNumber(raw));
}

function normalizeCoveredFiscalMonths(months) {
  const normalized = [...new Set((months || [])
    .map((month) => Number(month))
    .filter((month) => Number.isInteger(month) && month >= 1 && month <= 12))]
    .sort((left, right) => left - right);
  return normalized.length ? normalized : null;
}

function parseFiscalPeriodRangeFromName(fileName, fallbackYear = 2026) {
  const text = String(fileName || '');
  const match = text.match(/\b(0?[1-9]|1[0-2])\s*[-_]\s*(0?[1-9]|1[0-2])\s*[-_ ]+\s*(20\d{2}|\d{2})\b/);
  if (!match) return null;
  let year = Number(match[3]);
  if (year < 100) year += 2000;
  if (!Number.isInteger(year)) year = fallbackYear;
  const firstMonth = Number(match[1]);
  const lastMonth = Number(match[2]);
  const fromMonth = Math.min(firstMonth, lastMonth);
  const toMonth = Math.max(firstMonth, lastMonth);
  const covered = [];
  for (let month = fromMonth; month <= toMonth; month += 1) {
    covered.push(month);
  }
  return {
    fiscal_period_year: year,
    fiscal_period_month: toMonth,
    fiscal_period_kind: 'month',
    covered_fiscal_months: normalizeCoveredFiscalMonths(covered),
    source: 'file_name_range',
    confidence: 0.75
  };
}

function parseFiscalPeriod(fileName, text, fallbackYear = 2026) {
  const fromNameRange = parseFiscalPeriodRangeFromName(fileName, fallbackYear);
  if (fromNameRange) return fromNameRange;
  const fromFiscal = text.match(/Per[ií]odo\s+Fiscal:\s*(0?[0-9]|1[0-2])[\/.-](20\d{2}|\d{2})/i);
  const fromText = text.match(/(?:periodo|per[ií]odo|mes)\s*[:\-]?\s*(0?[1-9]|1[0-2])[\/.-](20\d{2}|\d{2})/i);
  const fromName = String(fileName || '').match(/\b(0?[1-9]|1[0-2])[-_ ]?(20\d{2}|\d{2})\b/);
  const match = fromFiscal || fromText || fromName;
  if (!match) {
    return { fiscal_period_year: fallbackYear, fiscal_period_month: null, fiscal_period_kind: 'year', covered_fiscal_months: null, source: 'processing_year_fallback', confidence: 0.2 };
  }
  const numericMonth = Number(match[1]);
  let year = Number(match[2]);
  if (year < 100) year += 2000;
  if (match === fromFiscal && numericMonth === 0) {
    return { fiscal_period_year: year, fiscal_period_month: null, fiscal_period_kind: 'year', covered_fiscal_months: null, source: 'fiscal_period_label', confidence: 0.85 };
  }
  return { fiscal_period_year: year, fiscal_period_month: numericMonth, fiscal_period_kind: 'month', covered_fiscal_months: normalizeCoveredFiscalMonths([numericMonth]), source: match === fromName ? 'file_name' : 'pdf_text', confidence: match === fromName ? 0.7 : 0.85 };
}

function cleanExtractedLabel(value) {
  return normalizeWhitespace(value).replace(/[.;,]+$/, '').trim() || null;
}

function parseServiceReason(text) {
  const patterns = [
    /Servicio:\s*([A-ZÁÉÍÓÚÑ0-9][A-ZÁÉÍÓÚÑ0-9 ._\/-]*?)(?=\s+Cod\.?\s+de\s+Ente:|\s+Identificaci[oó]n:|\s+Cuenta\s+de\s+D[eé]bito:|\s+Anotaci[oó]n\s+Personal:|\s+Vencimiento\b|$)/i,
    /Servicio\s+([A-ZÁÉÍÓÚÑ0-9][A-ZÁÉÍÓÚÑ0-9 ._\/-]*?)(?=\s+Datos\s+del\s+pagador|\s+Datos\s+particulares|\s+Identificaci[oó]n\b|\s+Estado\b|$)/i,
  ];
  for (const pattern of patterns) {
    const match = text.match(pattern);
    if (match) return cleanExtractedLabel(match[1]);
  }
  return null;
}

function parseTransferReason(text) {
  const motivoMatch = text.match(/Motivo\s+Tipo\s+de\s+transferencia\s+([A-ZÁÉÍÓÚÑ0-9][A-ZÁÉÍÓÚÑ0-9 ._\/-]*?)(?=\s+Datos\s+del\s+destinatario|\s+Razon\s+Social\b|$)/i);
  if (motivoMatch) return cleanExtractedLabel(motivoMatch[1]);
  const descMatch = text.match(/Descripci[oó]n:\s*([A-ZÁÉÍÓÚÑ0-9][A-ZÁÉÍÓÚÑ0-9 ._\/-]*?)(?=\s+CUIL\/CUIT|\s+Fecha\s+de\s+Generaci[oó]n|\s+Concepto:|$)/i);
  if (descMatch) return cleanExtractedLabel(descMatch[1]);
  return null;
}

function parseVepReason(text) {
  const match = text.match(/Pago\s+de:\s*([A-ZÁÉÍÓÚÑ0-9][A-ZÁÉÍÓÚÑ0-9 ._\/-]*?)(?=\s+Concepto:|\s+Subconcepto:|\s+Per[ií]odo\s+Fiscal:|\s+N[uú]mero\s+de\s+VEP:|$)/i);
  const rawReason = match ? cleanExtractedLabel(match[1]) : null;
  if (!rawReason) return null;
  const suffixMatch = rawReason.match(/^(.*?)\s+-\s+(SOLO\s+PAGO)$/i);
  if (!suffixMatch) return { reason: rawReason, note: null, raw_reason: rawReason };
  return {
    reason: cleanExtractedLabel(suffixMatch[1]),
    note: normalizeWhitespace(suffixMatch[2]).toUpperCase(),
    raw_reason: rawReason
  };
}

function parseVepNumber(text) {
  const match = text.match(/N[uú]mero\s+de\s+VEP:\s*(\d{6,})/i);
  return match ? cleanExtractedLabel(match[1]) : null;
}

function parseIssuerBank(text) {
  const candidates = [
    { name: 'Banco Credicoop Coop. Ltdo.', pattern: /Banco\s+Credicoop(?:\s+Coop\.?\s+Ltda?\.?|\s+Cooperativo\s+Ltda?\.?)?/i },
    { name: 'Banco Galicia', pattern: /(?:Banco\s+)?Galicia/i },
    { name: 'Banco de la Nacion Argentina', pattern: /Banco\s+(?:de\s+la\s+)?Naci[oó]n|\bBNA\b/i },
    { name: 'Banco Provincia', pattern: /Banco\s+Provincia/i },
    { name: 'Banco Santander', pattern: /(?:Banco\s+)?Santander/i },
    { name: 'BBVA', pattern: /\bBBVA\b|Franc[eé]s/i },
    { name: 'Banco Macro', pattern: /Banco\s+Macro|\bMacro\b/i },
    { name: 'ICBC', pattern: /\bICBC\b/i },
    { name: 'Mercado Pago', pattern: /Mercado\s+Pago/i },
    { name: 'Uala', pattern: /\bUal[aá]\b/i },
  ];

  for (const candidate of candidates) {
    if (candidate.pattern.test(text)) return candidate.name;
  }
  return null;
}

function parsePersonalAnnotation(text) {
  const match = text.match(/Anotaci[oó]n\s+Personal:\s*([A-ZÁÉÍÓÚÑ0-9][A-ZÁÉÍÓÚÑ0-9 ._\/-]*?)(?=\s+Vencimiento\b|\s+Importe\b|$)/i);
  return match ? cleanExtractedLabel(match[1]) : null;
}

function parsePaymentReference(text) {
  const patterns = [
    /Fecha\s+Nro\s+Transacci[oó]n\s+\d{1,2}[\/.-]\d{1,2}[\/.-]\d{2,4}\s*-?\s*\d{1,2}:\d{2}(?::\d{2})?\s+(\d{6,})/i,
    /Nro\s+Transacci[oó]n(?:\s+\d{1,2}[\/.-]\d{1,2}[\/.-]\d{2,4})?(?:\s*-?\s*\d{1,2}:\d{2}(?::\d{2})?)?\s+(\d{6,})/i,
    /Nro\s+de\s+Operaci[oó]n\s+(\d{6,})/i,
    /Identificador\s+de\s+la\s+operaci[oó]n:?\s*([A-Z0-9-]+)/i,
  ];
  for (const pattern of patterns) {
    const match = text.match(pattern);
    if (match) return cleanExtractedLabel(match[1]);
  }
  return null;
}

const VEHICLE_PATENT_CATEGORY_BY_PLATE = {
  AC743LH: 'Patente 500',
  AG437RG: 'Patente Amarok',
  AG453WA: 'Patente Berlingo',
  AE082TC: 'Patente C3',
};

function isVehiclePatentCategory(source) {
  const path = Array.isArray(source.category_path) ? source.category_path : [];
  const drivePath = String(source.drive_path || '');
  return path.includes('Patentes Vehiculos') || drivePath.includes('Patentes Vehiculos');
}

function extractArbaVehiclePatentPages(text) {
  const rawText = String(text || '');
  const rawPages = rawText.includes('\f')
    ? rawText.split(/\f+/)
    : rawText.split(/(?=Identificador\s+de\s+la\s+operaci[oó]n:?)/i);
  const pages = rawPages.map(page => normalizeWhitespace(page)).filter(Boolean);
  return pages.map((pageText, index) => {
    const plateMatch = pageText.match(/\b([A-Z]{2}[0-9]{3}[A-Z]{2})\s+\d{3}\/\d{2}\b/i);
    if (!plateMatch) return null;
    const plate = plateMatch[1].toUpperCase();
    const vehicleFolder = VEHICLE_PATENT_CATEGORY_BY_PLATE[plate] || null;
    return {
      page_index: index,
      page_number: index + 1,
      page_count: pages.length,
      plate,
      vehicle_folder: vehicleFolder,
      raw_text: pageText,
    };
  }).filter(Boolean);
}

return items.flatMap((item, index) => {
  const pairedIndex = Array.isArray(item.pairedItem) ? item.pairedItem[0]?.item : item.pairedItem?.item;
  const source = $('Descargar archivo').all()[pairedIndex]?.json || item.json;
  const fullPdfText = String(item.json.text || item.json.data || '');
  const extractionError = item.json.error || null;
  const patentPages = isVehiclePatentCategory(source) ? extractArbaVehiclePatentPages(fullPdfText) : [];
  const parts = patentPages.length > 1 ? patentPages : [{ raw_text: normalizeWhitespace(fullPdfText), page_index: null, page_number: null, page_count: null, plate: null, vehicle_folder: null }];

  return parts.map((part) => {
  const pdfText = part.raw_text;
  const hasText = pdfText.length >= 80;
  const paymentDate = hasText ? parseDate(pdfText) : null;
  const amount = hasText ? parseAmount(pdfText) : null;
  const fiscalPeriod = parseFiscalPeriod(source.name, pdfText, source.processing_year || 2026);
  const categoryPath = part.vehicle_folder
    ? ['Patentes Vehiculos', part.vehicle_folder]
    : (source.category_path || []);
  const originalDriveFileId = source.drive_file_id || source.id;
  const logicalDriveFileId = part.plate
    ? originalDriveFileId + '#page=' + part.page_number + '#plate=' + part.plate
    : originalDriveFileId;
  const logicalDrivePath = part.vehicle_folder
    ? (
        String(source.drive_path || '').includes('Patentes Vehiculos/2026/')
          ? String(source.drive_path || '').replace('Patentes Vehiculos/2026/', 'Patentes Vehiculos/' + part.vehicle_folder + '/2026/')
          : String(source.drive_path || '').replace(/Patentes Vehiculos\/[^/]+(?:\/2026)?\//, 'Patentes Vehiculos/' + part.vehicle_folder + '/2026/')
      ) + '#page=' + part.page_number
    : source.drive_path;
  const currency = /\b(?:usd|u\$s)\b/i.test(pdfText) ? 'USD' : (/\$|\bars\b|pesos?/i.test(pdfText) ? 'ARS' : null);
  const serviceReason = hasText ? parseServiceReason(pdfText) : null;
  const transferReason = hasText ? parseTransferReason(pdfText) : null;
  const vepReasonData = hasText ? parseVepReason(pdfText) : null;
  const vepReason = vepReasonData?.reason || null;
  const vepReasonNote = vepReasonData?.note || null;
  const vepRawReason = vepReasonData?.raw_reason || null;
  const vepNumber = hasText ? parseVepNumber(pdfText) : null;
  const personalAnnotation = hasText ? parsePersonalAnnotation(pdfText) : null;
  const paymentReference = hasText ? parsePaymentReference(pdfText) : null;
  const issuerBank = hasText ? parseIssuerBank(pdfText) : null;
  const categoryFallbackReason = Array.isArray(source.category_path) && source.category_path.length
    ? source.category_path[source.category_path.length - 1]
    : null;
  const reason = serviceReason || vepReason || transferReason || categoryFallbackReason || null;
  const reviewReasons = [];

  if (extractionError) reviewReasons.push('pdf_text_extraction_error');
  if (!hasText) reviewReasons.push('pdf_without_extractable_text_or_scanned');
  if (hasText && !paymentDate) reviewReasons.push('payment_date_not_detected');
  if (hasText && !amount) reviewReasons.push('amount_not_detected');
  if (hasText && !reason) reviewReasons.push('reason_not_detected');
  if (fiscalPeriod.source === 'processing_year_fallback') reviewReasons.push('fiscal_period_not_detected');
  if (part.plate && !part.vehicle_folder) reviewReasons.push('vehicle_patent_plate_not_mapped');
  if (hasText && !issuerBank) reviewReasons.push('issuer_not_detected_in_pdf_text');

  const processed = hasText && paymentDate && amount && reason && issuerBank && fiscalPeriod.source !== 'processing_year_fallback';

  return {
    json: {
      ...source,
      id: logicalDriveFileId,
      drive_file_id: logicalDriveFileId,
      original_drive_file_id: originalDriveFileId,
      drive_path: logicalDrivePath,
      category_path: categoryPath,
      source_kind: hasText ? 'pdf_text' : 'pdf_scanned',
      payment_date: paymentDate,
      payment_time: null,
      fiscal_period_year: fiscalPeriod.fiscal_period_year,
      fiscal_period_month: fiscalPeriod.fiscal_period_month,
      fiscal_period_kind: fiscalPeriod.fiscal_period_kind,
      covered_fiscal_months: fiscalPeriod.covered_fiscal_months,
      amount,
      currency,
      reason,
      reference: paymentReference || vepNumber,
      issuer: issuerBank,
      payee: null,
      user_note: personalAnnotation || vepReasonNote,
      raw_text: pdfText || null,
      extracted_data: {
        stage: 'final_pdf_text_first_pass',
        extractor: 'n8n_readPDF_plus_rules',
        source_kind: hasText ? 'pdf_text' : 'pdf_scanned',
        text_length: pdfText.length,
        drive_path: logicalDrivePath || null,
        category_path: categoryPath,
        original_drive_path: source.drive_path || null,
        original_drive_file_id: originalDriveFileId,
        logical_drive_file_id: logicalDriveFileId,
        pdf_page_number: part.page_number,
        pdf_page_index: part.page_index,
        pdf_page_count: part.page_count,
        vehicle_patent_plate: part.plate,
        vehicle_patent_folder: part.vehicle_folder,
        vehicle_patent_mapping_source: part.plate ? 'VEHICLE_PATENT_CATEGORY_BY_PLATE' : null,
        file_modified_at: source.modifiedTime || null,
        mime_type: source.mimeType || null,
        md5Checksum: source.drive_md5_checksum || source.md5Checksum || null,
        drive_md5_checksum: source.drive_md5_checksum || source.md5Checksum || null,
        size: source.size || null,
        sha256: source.sha256 || null,
        content_hash: source.content_hash || source.sha256 || null,
        content_hash_algorithm: source.content_hash_algorithm || (source.sha256 ? 'sha256' : null),
        extraction_error: extractionError,
        service_reason: serviceReason,
        transfer_reason: transferReason,
        vep_reason: vepReason,
        vep_reason_note: vepReasonNote,
        vep_raw_reason: vepRawReason,
        vep_number: vepNumber,
        personal_annotation: personalAnnotation,
        payment_reference: paymentReference,
        issuer_bank: issuerBank,
        issuer_source: issuerBank ? 'pdf_text_bank_name' : (hasText ? 'not_detected_in_pdf_text' : 'ocr_or_vision_pending'),
        fiscal_period_source: fiscalPeriod.source,
        covered_fiscal_months: fiscalPeriod.covered_fiscal_months || null,
        field_confidence: {
          raw_text: hasText ? 0.9 : 0,
          payment_date: paymentDate ? 0.65 : 0,
          amount: amount ? 0.65 : 0,
          currency: currency ? 0.6 : 0,
          fiscal_period: fiscalPeriod.confidence,
          reason: serviceReason || vepReason ? 0.85 : (transferReason ? 0.75 : (categoryFallbackReason ? 0.55 : 0)),
          reference: (paymentReference || vepNumber) ? 0.85 : 0,
          issuer: issuerBank ? 0.9 : 0
        },
        review_reasons: reviewReasons
      },
      processing_status: processed ? 'processed' : 'review_required',
      processing_error: extractionError
    },
    binary: item.binary
  };
  });
});

return items.map((item, index) => {
  const source = $('Normalizar extracción PDF').all()[index]?.json || item.json;
  const sha256 = item.json.sha256 || item.json.data || null;
  const driveMd5Checksum = source.md5Checksum || source.drive_md5_checksum || null;
  return {
    json: {
      ...source,
      sha256,
      content_hash: sha256,
      content_hash_algorithm: sha256 ? 'sha256' : null,
      drive_md5_checksum: driveMd5Checksum,
    },
    binary: item.binary,
  };
});

function normalizeWhitespace(value) {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

function normalizeConfidence(value) {
  if (typeof value === 'number') return value;
  const text = normalizeWhitespace(value).toLowerCase();
  if (!text) return 0;
  if (text === 'alta' || text === 'alto' || text === 'high') return 0.9;
  if (text === 'media' || text === 'medio' || text === 'medium') return 0.6;
  if (text === 'baja' || text === 'bajo' || text === 'low') return 0.3;
  const numeric = Number(text.replace(',', '.'));
  return Number.isFinite(numeric) ? numeric : 0;
}

function safeJsonParse(value) {
  const text = normalizeWhitespace(value);
  if (!text) return null;
  try {
    return JSON.parse(text);
  } catch {}
  const fenced = text.match(new RegExp('\`{3}(?:json)?\\\\s*([\\\\s\\\\S]*?)\`{3}', 'i'));
  if (fenced) {
    try { return JSON.parse(fenced[1]); } catch {}
  }
  const objectMatch = text.match(/\{[\s\S]*\}/);
  if (objectMatch) {
    try { return JSON.parse(objectMatch[0]); } catch {}
  }
  return null;
}

function responseText(payload) {
  if (payload?.output_text) return payload.output_text;
  const parts = [];
  for (const output of payload?.output || []) {
    for (const content of output?.content || []) {
      if (typeof content?.text === 'string') parts.push(content.text);
    }
  }
  return parts.join('\n');
}

function withReviewReason(item, reason, extra = {}) {
  const existingReasons = Array.isArray(item.json.extracted_data?.review_reasons)
    ? item.json.extracted_data.review_reasons
    : [];
  const reviewReasons = Array.from(new Set([...existingReasons, reason]));
  return {
    json: {
      ...item.json,
      ...extra,
      extracted_data: {
        ...(item.json.extracted_data || {}),
        ...extra.extracted_data,
        review_reasons: reviewReasons,
      },
      processing_status: 'review_required',
    },
    binary: item.binary,
  };
}

const apiKey = $env.OPENAI_FINANZAS_API_KEY || '';
const openaiKeySource = $env.OPENAI_FINANZAS_API_KEY ? 'OPENAI_FINANZAS_API_KEY' : 'missing';
const model = $env.OPENAI_FINANZAS_MODEL || 'gpt-4.1-mini-2025-04-14';
const httpRequest = this.helpers.httpRequest.bind(this.helpers);

return await Promise.all(items.map(async (item, index) => {
  if (item.json.issuer) return item;

  const pairedIndex = Array.isArray(item.pairedItem) ? item.pairedItem[0]?.item : item.pairedItem?.item;
  const downloadedItem = $('Descargar archivo').all()[pairedIndex] || {};
  const binary = item.binary?.data || downloadedItem.binary?.data;
  let base64 = '';
  if (binary?.data && binary.data !== 'filesystem-v2') {
    base64 = binary.data;
  } else if (binary?.id || binary?.data === 'filesystem-v2') {
    const buffer = await this.helpers.getBinaryDataBuffer(index, 'data');
    base64 = Buffer.from(buffer).toString('base64');
  }
  const mimeType = item.json.mimeType || binary?.mimeType || downloadedItem.json?.mimeType || 'application/octet-stream';
  const fileName = item.json.name || item.json.file_name || binary?.fileName || downloadedItem.json?.name || 'documento';

  if (!apiKey) {
    return withReviewReason(item, 'openai_finanzas_api_key_missing', {
      extracted_data: {
        issuer_source: 'ocr_or_vision_pending',
        ocr_vision_model: model,
        openai_key_source: openaiKeySource,
      },
    });
  }
  if (!base64) {
    return withReviewReason(item, 'binary_missing_for_ocr_or_vision', {
      extracted_data: {
        issuer_source: 'ocr_or_vision_pending',
        ocr_vision_model: model,
        openai_key_source: openaiKeySource,
      },
    });
  }

  const fileContent = mimeType.startsWith('image/')
    ? { type: 'input_image', image_url: 'data:' + mimeType + ';base64,' + base64 }
    : { type: 'input_file', filename: fileName, file_data: 'data:' + mimeType + ';base64,' + base64 };

  const instruction = [
    'Analiza este comprobante de pago argentino.',
    'Tu tarea principal es identificar la entidad pagadora/emisora desde texto visible, OCR o logo del banco/billetera.',
    'La entidad pagadora es el banco, billetera o home banking desde donde se emitio el pago o transferencia, no el destinatario.',
    'No inventes. Si no estas seguro, usa issuer=null, confidence baja y needs_review=true.',
    'Responde solo JSON valido con estas claves exactas: issuer, issuer_source, confidence, raw_text, needs_review, review_reasons.',
    'issuer_source debe ser uno de: logo_visual, ocr_text, visual_and_ocr_text, not_detected.',
  ].join(' ');

  try {
    const payload = await httpRequest({
      method: 'POST',
      url: 'https://api.openai.com/v1/responses',
      headers: {
        Authorization: 'Bearer ' + apiKey,
        'Content-Type': 'application/json',
      },
      body: {
        model,
        temperature: 0,
        input: [
          {
            role: 'user',
            content: [
              { type: 'input_text', text: instruction },
              fileContent,
            ],
          },
        ],
      },
      json: true,
    });

    const parsed = safeJsonParse(responseText(payload)) || {};
    const issuer = normalizeWhitespace(parsed.issuer) || null;
    const confidence = normalizeConfidence(parsed.confidence);
    const issuerSource = ['logo_visual', 'ocr_text', 'visual_and_ocr_text'].includes(parsed.issuer_source)
      ? parsed.issuer_source
      : (issuer ? 'ocr_text' : 'not_detected');
    const ocrText = normalizeWhitespace(parsed.raw_text);
    const reviewReasons = Array.isArray(parsed.review_reasons)
      ? parsed.review_reasons.map(normalizeWhitespace).filter(Boolean)
      : [];
    const trustedIssuer = issuer && Number.isFinite(confidence) && confidence >= 0.75;

    return {
      json: {
        ...item.json,
        issuer: trustedIssuer ? issuer : null,
        raw_text: item.json.raw_text || ocrText || null,
        extracted_data: {
          ...(item.json.extracted_data || {}),
          issuer_bank: trustedIssuer ? issuer : null,
          issuer_source: trustedIssuer ? issuerSource : 'ocr_or_vision_low_confidence',
          ocr_vision_model: payload.model || model,
          openai_key_source: openaiKeySource,
          ocr_vision_confidence: Number.isFinite(confidence) ? confidence : 0,
          ocr_vision_raw_text_length: ocrText.length,
          ocr_vision_response_id: payload.id || null,
          review_reasons: trustedIssuer
            ? reviewReasons.filter(reason => reason !== 'issuer_requires_ocr_or_vision')
            : Array.from(new Set([...reviewReasons, 'issuer_not_detected_by_ocr_or_vision'])),
          field_confidence: {
            ...(item.json.extracted_data?.field_confidence || {}),
            issuer: trustedIssuer ? confidence : 0,
          },
        },
        processing_status: trustedIssuer && item.json.payment_date && item.json.amount && item.json.reason
          ? 'processed'
          : 'review_required',
      },
      binary: item.binary,
    };
  } catch (error) {
    return withReviewReason(item, 'ocr_or_vision_openai_error', {
      processing_error: String(error?.message || error).slice(0, 500),
      extracted_data: {
        issuer_source: 'ocr_or_vision_error',
        ocr_vision_model: model,
        openai_key_source: openaiKeySource,
      },
    });
  }
}));
